tool_input.command:
$dir = "D:\repository\苏州市房地产监测V3\.tmp-bug6246"
Add-Type -AssemblyName System.Drawing
# Measure the dialog left/right edges across frames by scanning rows
# The dialog appears roughly centered. We'll detect vertical white dialog border at row y=200
$count = 83
$results = @()
for ($i=0; $i -lt $count; $i++) {
  $img = [System.Drawing.Image]::FromFile("$dir\frame_$i.png")
  $bmp = New-Object System.Drawing.Bitmap($img)
  $y = 400
  $left = -1; $right = -1
  # scan for dialog edges: dialog is white (255) vs page bg. Use row y, find first/last near-white run within x 400..1500
  for ($x=380; $x -lt 1500; $x++){
    $c = $bmp.GetPixel($x,$y)
    if ($c.R -gt 240 -and $c.G -gt 240 -and $c.B -gt 240){ if($left -lt 0){$left=$x}; $right=$x }
  }
  $results += [pscustomobject]@{frame=$i; left=$left; right=$right; width=($right-$left)}
  $bmp.Dispose(); $img.Dispose()
}
$results | Format-Table -AutoSize | Out-String -Width 200

