import { chromium } from '@playwright/test'
import fs from 'fs'
import path from 'path'

const DIST = path.resolve('dist')
const bjsCss = fs.readFileSync(path.join(DIST, 'assets/index-CByIjPBI.css'), 'utf8')

// Build a static HTML replicating: el-dialog wrapper (flex-centered) > el-dialog.zs-dialog--form-double
// > header + body(.el-dialog__body) > .dialog-box > .form-box > form with N=22 rows in 2 cols,
// plus one el-select (房屋类型) whose dropdown we toggle.
// We inject the real compiled CSS so the layout matches production exactly.

const rows = []
const fields = [
  '房屋编号','楼幢号','单元名称','户室号','房屋统一编码','户型',
  '房屋坐落','不动产单元号','房屋朝向','所在层','层编号','层高',
  '房屋用途','公安门牌号','预测建筑面积','预测套内建筑面积','预测分摊建筑面积',
  '实测建筑面积','实测套内建筑面积','实测分摊建筑面积','房屋类型','所属主房'
]
fields.forEach((label, i) => {
  const isSelect = ['户型','房屋朝向','房屋用途','房屋类型'].includes(label)
  const control = isSelect
    ? `<div class="el-select" id="sel-${i}"><div class="el-input el-input--suffix"><input class="el-input__inner" value="${label==='房屋类型'?'自行车库':''}" readonly><span class="el-input__suffix"><i class="el-input__icon el-icon-arrow-up"></i></span></div></div>`
    : `<div class="el-input"><input class="el-input__inner" value="127.55"></div>`
  rows.push(`<div class="el-col el-col-12"><div class="el-form-item"><label class="el-form-item__label">${label}</label><div class="el-form-item__content">${control}</div></div></div>`)
})

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${bjsCss}</style>
<style>
  html,body{margin:0;height:100%;}
  /* emulate el-dialog wrapper: fixed full-viewport flex centered */
  .page-spacer{height:200vh;} /* give document a scrollbar like real page */
</style></head>
<body>
<div class="el-popup-parent" style="height:100vh;overflow:auto;">
  <div class="page-spacer"></div>
  <div class="el-dialog__wrapper zs-dialog" style="position:fixed;inset:0;">
    <div class="el-dialog zs-dialog--form-double" style="width:1000px;">
      <div class="el-dialog__header"><span class="el-dialog__title">户室编辑</span></div>
      <div class="el-dialog__body">
        <div class="dialog-box">
          <div class="form-box" id="formBox">
            <form class="el-form el-form--label-right" style="display:flow-root;">
              ${rows.join('\n')}
            </form>
          </div>
        </div>
      </div>
      <div class="el-dialog__footer"><div class="dialog-footer"><button class="el-button">取消</button><button class="el-button el-button--primary">确定</button></div></div>
    </div>
  </div>
</div>
<script>
  // Simulate what applyScrollableBody does when height is capped
  window.__setScrollable = function(on){
    var body = document.querySelector('.el-dialog__body');
    if(on){ body.style.flex='1 1 auto'; body.style.minHeight='0'; body.style.overflowY='auto'; }
    else { body.style.flex=''; body.style.minHeight=''; body.style.overflowY=''; }
    var dlg = document.querySelector('.el-dialog');
    if(on){ dlg.style.height = Math.round(window.innerHeight*0.92 - 200)+'px'; }
    else { dlg.style.height = 'auto'; }
  };
</script>
</body></html>`

fs.mkdirSync(path.resolve('.tmp-repro'), { recursive: true })
const htmlPath = path.resolve('.tmp-repro/page.html')
fs.writeFileSync(htmlPath, html)

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1860, height: 900 } })
await page.goto('file://' + htmlPath.replace(/\\/g, '/'))
await page.waitForTimeout(300)

async function measureFormWidth() {
  return await page.evaluate(() => {
    const fb = document.getElementById('formBox')
    const body = document.querySelector('.el-dialog__body')
    return {
      formClient: fb.clientWidth,
      formScroll: fb.scrollWidth,
      bodyClient: body.clientWidth,
      bodyScroll: body.scrollHeight,
      bodyOffset: body.offsetHeight
    }
  })
}

console.log('=== NOT scrollable (dialog height auto) ===')
await page.evaluate(() => window.__setScrollable(false))
await page.waitForTimeout(150)
console.log(JSON.stringify(await measureFormWidth()))

console.log('\n=== Simulate select OPEN -> toggle scrollable ON (as calculateHeight() would when content taller than cap) ===')
await page.evaluate(() => window.__setScrollable(true))
await page.waitForTimeout(200)
console.log(JSON.stringify(await measureFormWidth()))

console.log('\n=== toggle again OFF (select CLOSE) ===')
await page.evaluate(() => window.__setScrollable(false))
await page.waitForTimeout(200)
console.log(JSON.stringify(await measureFormWidth()))

await browser.close()

