      <div class="dialog-box"><div class="form-box" id="formBox">
        <form class="el-form el-form--label-right" style="display:flow-root">${rows}</form>
      </div></div>
    </div>
    <div class="el-dialog__footer"><div class="dialog-footer"><button class="el-button">取消</button></div></div>
  </div>
</div></div>
<script>
window.__cap = function(on){
  var dlg=document.querySelector('.el-dialog'), body=document.getElementById('body');
  if(on){ dlg.style.height=Math.round(window.innerHeight*0.92-200)+'px'; body.style.flex='1 1 auto'; body.style.minHeight='0'; body.style.overflowY='auto'; }
  else { dlg.style.height='auto'; body.style.flex=''; body.style.minHeight=''; body.style.overflowY=''; }
};
</script></body></html>`
