async function run(execPathLabel, launchOpts) {
  const b = await chromium.launch(launchOpts)
  const p = await b.newPage({ viewport: { width: 1860, height: 900 } })
  await p.goto('file://' + path.resolve('.tmp-repro/verify.html').replace(/\\/g, '/'))
  await p.waitForTimeout(200)
  const measure = () => p.evaluate(() => {
    const fb = document.getElementById('formBox'); const body = document.getElementById('body')
    const ins = fb.querySelectorAll('.el-input__inner'); let left = 1e9, right = -1
    ins.forEach(el => { const r = el.getBoundingClientRect(); if (r.left < left) left = r.left; if (r.right > right && r.right < document.body.clientWidth - 50) right = r.right })
    return { formClientW: fb.clientWidth, bodyClientW: body.clientWidth, bodyGutter: body.offsetWidth - body.clientWidth, lastInputRight: Math.round(right) }
  })
  await p.evaluate(() => window.__cap(false)); await p.waitForTimeout(80)
  const autoState = await measure()
  await p.evaluate(() => window.__cap(true)); await p.waitForTimeout(120)
  const cappedState = await measure()
  await b.close()
  return { autoState, cappedState }
}

const opts = { executablePath: 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe', headless: true }
const res = await run('edge', opts)
console.log('AUTO   (no scroll):', JSON.stringify(res.autoState))
