tool_input.content:
import { chromium } from '@playwright/test'
import fs from 'fs'
import path from 'path'

const DIST = path.resolve('dist')
const cssFile = fs.readdirSync(path.join(DIST, 'assets')).filter(f => /^index-.*\.css$/.test(f) && !f.includes('bak')).sort().pop()
const css = fs.readFileSync(path.join(DIST, 'assets', cssFile), 'utf8')
console.log('using css:', cssFile)

const labels = ['l1','l2','l3','l4','l5','l6','l7','l8','l9','l10','l11','l12','l13','l14','l15','l16','l17','l18','l19','l20','l21','l22']
const rows = labels.map((label) => `<div class="el-col el-col-12"><div class="el-form-item"><label class="el-form-item__label">${label}</label><div class="el-form-item__content"><div class="el-input"><input class="el-input__inner" value="127.55"></div></div></div></div>`).join('\n')

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${css}</style></head><body style="margin:0">
<div class="el-popup-parent" style="height:100vh;overflow:auto"><div style="height:200vh"></div>
<div class="el-dialog__wrapper zs-dialog" style="position:fixed;inset:0">
  <div class="el-dialog zs-dialog--form-double" style="width:1000px">
    <div class="el-dialog__header"><span class="el-dialog__title">t</span></div>
    <div class="el-dialog__body" id="body">
      <div class="dialog-box"><div class="form-box" id="formBox">
        <form class="el-form el-form--label-right" style="display:flow-root">${rows}</form>
      </div></div>
    </div>
    <div class="el-dialog__footer"><div class="dialog-footer"><button class="el-button">x</button></div></div>
  </div>
</div></div>
<script>
window.__cap = function(on){
  var dlg=document.querySelector('.el-dialog'), body=document.getElementById('body');
  if(on){ dlg.style.height=Math.round(window.innerHeight*0.92-200)+'px'; body.style.flex='1 1 auto'; body.style.minHeight='0'; body.style.overflowY='auto'; }
  else { dlg.style.height='auto'; body.style.flex=''; body.style.minHeight=''; body.style.overflowY=''; }
};
</script></body></html>`
fs.writeFileSync(path.resolve('.tmp-repro/verify.html'), html)

const b = await chromium.launch({ executablePath: 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe', headless: true })
const p = await b.newPage({ viewport: { width: 1860, height: 900 } })
await p.goto('file://' + path.resolve('.tmp-repro/verify.html').replace(/\\/g, '/'))
await p.waitForTimeout(200)
const measure = () => p.evaluate(() => {
  const fb = document.getElementById('formBox'); const body = document.getElementById('body')
  return { formClientW: fb.clientWidth, bodyClientW: body.clientWidth, bodyGutter: body.offsetWidth - body.clientWidth }
})
await p.evaluate(() => window.__cap(false)); await p.waitForTimeout(100)
const autoState = await measure()
await p.evaluate(() => window.__cap(true)); await p.waitForTimeout(150)
const cappedState = await measure()
console.log('AUTO  :', JSON.stringify(autoState))
console.log('CAPPED:', JSON.stringify(cappedState))
console.log('formClientW delta:', autoState.formClientW - cappedState.formClientW)
console.log('bodyGutter delta:', autoState.bodyGutter - cappedState.bodyGutter)
await b.close()

